import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-02-08","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-02-08","date":"2023-02-08T00:00:00.000Z","updated":"2023-02-15T00:00:00.000Z","tags":["Ceph","RGW","Refactoring","Cloud Transition","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-02-08.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-02-08.md","lastUpdated":1780460162000}'),o={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-02-08.md"};function r(n,e,h,s,d,u){return t(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph存储系统开发讨论会" tabindex="-1">会议主题：Ceph存储系统开发讨论会 <a class="header-anchor" href="#会议主题-ceph存储系统开发讨论会" aria-label="Permalink to &quot;会议主题：Ceph存储系统开发讨论会&quot;">​</a></h4><h4 id="日期-2023年2月8日" tabindex="-1">日期：2023年2月8日 <a class="header-anchor" href="#日期-2023年2月8日" aria-label="Permalink to &quot;日期：2023年2月8日&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>预取功能（Prefetching）讨论</strong></p><ul><li>讨论了之前关于范围请求预取功能的拉取请求，该功能因OSD无法从EC池进行远程读取而受阻。不过，此问题已得到解决，并建议有人重新审视并尝试该功能，因为网络压缩和加密问题已得到解决。</li></ul></li><li><p><strong>云过渡问题讨论</strong></p><ul><li>讨论了从Noba MCG过渡到Azure时的问题，主要是因为对象名称中的连字符（hyphen）导致过渡失败。提出了通过添加特定的HTTP头来决定是否进行属性映射的解决方案，以便Noba能够适应该问题，并探讨了可能的技术实现细节。</li></ul></li><li><p><strong>RGW套件故障排查</strong></p><ul><li>报告了RGW套件在Ragweed上失败的状况，具体是由于Python导入问题导致的测试失败。讨论了可能的故障原因，包括Python库路径问题，并建议进一步调查和解决。</li></ul></li><li><p><strong>Google Summer of Code和Outreachy项目征集</strong></p><ul><li>提醒团队成员关于Google Summer of Code和Outreachy项目的征集，鼓励大家提出与Ceph相关的项目想法。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要有人重新审视并尝试预取功能。</li><li>对于云过渡问题，建议通过添加特定的HTTP头来解决，并探讨具体的技术实现。</li><li>对于RGW套件故障，需要进一步调查并解决Python导入问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>重新审视预取功能的拉取请求，并尝试实施。</li><li>设计和实现通过HTTP头来控制属性映射的解决方案。</li><li>调查并解决RGW套件的Python导入问题。</li><li>收集和提交与Ceph相关的Google Summer of Code和Outreachy项目想法。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，感谢所有参与者的贡献。</li></ul>',12)])])}const _=a(o,[["render",r]]);export{p as __pageData,_ as default};
